import pytest
from jose import jwt, jwe, jws, jwk, utils, constants, exceptions
from jose.exceptions import JWTError, ExpiredSignatureError, JWSSignatureError, JWSError, JOSEError
SECRET = b'unit-test-secret-key-0123456789'

def test_jwt_encode_decode_roundtrip():
    """jwt.encode then jwt.decode returns the original claims."""
    claims = {'sub': 'user-1', 'name': 'Alice'}
    token = jwt.encode(claims, SECRET, algorithm='HS256')
    assert jwt.decode(token, SECRET, algorithms=['HS256']) == claims

def test_jwt_decode_wrong_key_raises_jwt_error():
    """Decoding with the wrong key raises JWTError."""
    token = jwt.encode({'sub': 'user-1'}, SECRET, algorithm='HS256')
    with pytest.raises(JWTError):
        jwt.decode(token, b'wrong-key-0123456789', algorithms=['HS256'])

def test_jwt_decode_expired_raises_expired_signature_error():
    """A token whose exp is in the past raises ExpiredSignatureError."""
    token = jwt.encode({'sub': 'u', 'exp': 1}, SECRET, algorithm='HS256')
    with pytest.raises(ExpiredSignatureError):
        jwt.decode(token, SECRET, algorithms=['HS256'])

def test_jwt_get_unverified_header_returns_alg():
    """get_unverified_header returns the header dict with the alg."""
    token = jwt.encode({'sub': 'u'}, SECRET, algorithm='HS256')
    header = jwt.get_unverified_header(token)
    assert header['alg'] == 'HS256'
    assert header['typ'] == 'JWT'

def test_jwt_get_unverified_claims_returns_claims():
    """get_unverified_claims returns the claims without verification."""
    token = jwt.encode({'sub': 'u', 'role': 'admin'}, SECRET, algorithm='HS256')
    claims = jwt.get_unverified_claims(token)
    assert claims['sub'] == 'u'
    assert claims['role'] == 'admin'

def test_jws_sign_verify_roundtrip():
    """jws.sign then jws.verify returns the original payload."""
    payload = b'hello world'
    token = jws.sign(payload, SECRET, algorithm='HS256')
    assert jws.verify(token, SECRET, ['HS256']) == payload

def test_utils_base64url_roundtrip():
    """base64url_encode then base64url_decode returns the original bytes."""
    data = b'some test data \x00\x01\x02'
    encoded = utils.base64url_encode(data)
    assert utils.base64url_decode(encoded) == data

def test_utils_ensure_binary_coerces_str_to_bytes():
    """ensure_binary converts a str to its UTF-8 bytes."""
    assert utils.ensure_binary('hello') == b'hello'
    assert utils.ensure_binary(b'hello') == b'hello'
